import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import '../../itqan_journey/data/journey_auth_api.dart';
import '../../home/home_screen.dart';

class RegisterScreen extends StatefulWidget {const RegisterScreen({super.key});@override State<RegisterScreen> createState()=>_RegisterScreenState();}
class _RegisterScreenState extends State<RegisterScreen>{final _name=TextEditingController();final _email=TextEditingController();final _phone=TextEditingController();final _password=TextEditingController();bool _busy=false;late final JourneyAuthApi _api=JourneyAuthApi(client:http.Client());@override void dispose(){_name.dispose();_email.dispose();_phone.dispose();_password.dispose();super.dispose();}
Future<void> _register()async{if(_name.text.trim().isEmpty||_email.text.trim().isEmpty||_password.text.length<8){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('أكمل البيانات، وكلمة المرور 8 أحرف على الأقل.')));return;}setState(()=>_busy=true);try{await _api.register(name:_name.text.trim(),email:_email.text.trim(),password:_password.text,phone:_phone.text.trim());if(mounted)Navigator.pushAndRemoveUntil(context,MaterialPageRoute<void>(builder:(_)=>const HomeScreen()),(_)=>false);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>_busy=false);}}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('إنشاء حساب')),body:ListView(padding:const EdgeInsets.all(24),children:[TextField(controller:_name,decoration:const InputDecoration(labelText:'الاسم',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:_email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'البريد الإلكتروني',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:_phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'الهاتف (اختياري)',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:_password,obscureText:true,decoration:const InputDecoration(labelText:'كلمة المرور (8 أحرف على الأقل)',border:OutlineInputBorder())),const SizedBox(height:20),FilledButton(onPressed:_busy?null:_register,child:_busy?const CircularProgressIndicator():const Text('إنشاء الحساب'))]));}
